025","printed_pages":[24],"pdf_pages":[24]}},"uses":[[0],[5]]},{"data":{"id":"u01_l03_q013","unit_id":"u01","lesson_id":"u01_l03","difficulty":"easy","type":"multiple_choice","prompt":"أي وصف يحدد الإعجاز الغيبي كما يعرضه الكتاب؟","topic":"الإعجاز الغيبي","payload":{"options":[{"id":"o4","text":"تشريع تقسيم التركة فقط"},{"id":"o2","text":"وضع الإنسان توقعا غير محقق"},{"id":"o3","text":"دقة نطق الكلمات فقط"},{"id":"o1","text":"إخبار القرآن بأحداث مستقبلية ثم وقوعها كما أخبر"}]},"answer":{"option_id":"o1"},"explanation":"تعريف الدرس يقيد الإخبار بالأحداث المستقبلية التي وقعت كما أخبر القرآن.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[23],"pdf_pages":[23]}},"uses":[[0],[5]]}]$educational_content$::jsonb) item
